
(function(){const MENU_URL="https://mapas.bogota.gov.co/ideca/menu.json",menuContainer=document.getElementById("centralMenu"),menuWrapper=document.getElementById("navbarMenuOverlay"),navbarToggler=document.querySelector('.navbar-toggler[aria-controls="navbarNav"]'),navbarCollapse=document.getElementById("navbarNav");if(navbarToggler&&navbarCollapse){navbarToggler.addEventListener("click",function(){const expanded=navbarToggler.getAttribute("aria-expanded")==="true";navbarCollapse.classList.toggle("show",!expanded);navbarToggler.setAttribute("aria-expanded",String(!expanded));});navbarCollapse.addEventListener("keydown",function(event){if(event.key==="Escape"&&navbarCollapse.classList.contains("show")){navbarCollapse.classList.remove("show");navbarToggler.setAttribute("aria-expanded","false");navbarToggler.focus();}});navbarCollapse.addEventListener("click",function(event){if(event.target.closest("a[href]")){navbarCollapse.classList.remove("show");navbarToggler.setAttribute("aria-expanded","false");}});}if(!menuContainer||!menuWrapper){console.error("No se encontró #centralMenu o #navbarMenuOverlay");return;}async function loadMenu(){try{const response=await fetch(MENU_URL,{method:"GET",cache:"no-cache"});if(!response.ok)throw new Error(`Error HTTP al cargar el menú: ${response.status}`);const data=await response.json();if(!data||!Array.isArray(data.menu))throw new Error("La estructura del JSON no es válida");renderMenu(data.menu);menuWrapper.style.display="";}catch(error){console.error("No fue posible cargar el menú centralizado:",error);menuContainer.innerHTML="";menuWrapper.style.display="none";}}function renderMenu(items){menuContainer.innerHTML="";const activeItem=getActiveItem(items);items.forEach(item=>{const li=document.createElement("li");li.className="nav-item flex-fill";const hasChildren=Array.isArray(item.children)&&item.children.length>0;if(hasChildren)li.classList.add("dropdown");const link=document.createElement("a");link.className="nav-link";link.href=item.url;link.textContent=` ${item.label} `;if(isActive(item,activeItem)){link.classList.add("active");link.setAttribute("aria-current","page");}if(hasChildren){link.setAttribute("role","button");link.setAttribute("aria-expanded","false");}li.appendChild(link);if(hasChildren){const submenuId=`submenu-${item.id}`;const button=document.createElement("button");button.className="nav-dropdown-toggle";button.type="button";button.setAttribute("aria-expanded","false");button.setAttribute("aria-controls",submenuId);button.setAttribute("aria-label",`Expandir ${item.label}`);const icon=document.createElement("i");icon.className="fas fa-chevron-down";icon.setAttribute("aria-hidden","true");button.appendChild(icon);li.appendChild(button);const submenu=document.createElement("ul");submenu.id=submenuId;submenu.className="dropdown-menu dropdown-menu-columns";if(item.dropdownClass)submenu.classList.add(item.dropdownClass);item.children.forEach(child=>{const childLi=document.createElement("li"),childLink=document.createElement("a");childLink.className="dropdown-item";childLink.href=child.url;childLink.textContent=child.label;childLi.appendChild(childLink);submenu.appendChild(childLi);});li.appendChild(submenu);}menuContainer.appendChild(li);});initializeDropdowns();}function initializeDropdowns(){const buttons=document.querySelectorAll("#centralMenu .nav-dropdown-toggle");buttons.forEach(button=>{button.addEventListener("click",function(){const expanded=this.getAttribute("aria-expanded")==="true";buttons.forEach(otherButton=>{if(otherButton!==this){otherButton.setAttribute("aria-expanded","false");const otherMenuId=otherButton.getAttribute("aria-controls"),otherMenu=document.getElementById(otherMenuId),otherItem=otherButton.closest(".nav-item"),otherLink=otherItem?.querySelector(".nav-link"),otherLabel=otherLink?.textContent.trim()||"opciones";otherItem?.classList.remove("is-open");otherLink?.setAttribute("aria-expanded","false");otherButton.setAttribute("aria-label",`Expandir ${otherLabel}`);otherMenu?.classList.remove("show");}});this.setAttribute("aria-expanded",String(!expanded));const menuId=this.getAttribute("aria-controls"),menu=document.getElementById(menuId),menuItem=this.closest(".nav-item"),link=menuItem?.querySelector(".nav-link"),label=link?.textContent.trim()||"opciones";menuItem?.classList.toggle("is-open",!expanded);link?.setAttribute("aria-expanded",String(!expanded));this.setAttribute("aria-label",`${expanded?"Expandir":"Contraer"} ${label}`);menu?.classList.toggle("show",!expanded);});});}function getActiveItem(items){const current=new URL(window.location.href);return items.find(item=>[...(item.activeWhen||[]),item.url].some(pattern=>matchesUrl(current,pattern)));}function isActive(item,activeItem){return item.id===activeItem?.id;}function matchesUrl(current,target){try{if(typeof target!=="string"||!target.trim())return false;target=target.trim();if(target.startsWith("/"))return current.pathname===target||current.pathname.startsWith(target.endsWith("/")?target:target+"/");const normalizedTarget=target.includes("://")?target:`https://${target}`,targetUrl=new URL(normalizedTarget),sameDomain=current.hostname===targetUrl.hostname||current.hostname.endsWith("."+targetUrl.hostname);if(!sameDomain)return false;const targetPath=targetUrl.pathname;return current.pathname===targetPath||current.pathname.startsWith(targetPath.endsWith("/")?targetPath:targetPath+"/");}catch(error){console.error("Error comparando URL:",target,error);return false;}}loadMenu();})();
